import {
    LogicWrapper,
    MakeLogicType,
    actions,
    connect,
    kea,
    key,
    listeners,
    path,
    props,
    reducers,
    selectors,
} from 'kea'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

export interface TeamSettingToggleLogicProps {
    field: keyof TeamType
    label: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamSettingToggleLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    checked: boolean
    isSaving: boolean
    optimisticValue: boolean | null
    serverValue: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamSettingToggleLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    updateCurrentTeamFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    } // teamLogic
    updateCurrentTeamSuccess: (
        currentTeam: TeamPublicType | TeamType,
        payload?: Partial<TeamType> | undefined
    ) => {
        currentTeam: TeamPublicType | TeamType
        payload?: Partial<TeamType>
    } // teamLogic
    revert: () => {
        value: true
    }
    setValue: (value: boolean) => {
        value: boolean
    }
    settle: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamSettingToggleLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        serverValue: (currentTeam: TeamPublicType | TeamType | null, arg: any) => boolean
        checked: (optimisticValue: boolean | null, serverValue: boolean) => boolean
    }
}

export type teamSettingToggleLogicType = MakeLogicType<
    teamSettingToggleLogicValues,
    teamSettingToggleLogicActions,
    TeamSettingToggleLogicProps,
    teamSettingToggleLogicMeta
>

export const teamSettingToggleLogic: LogicWrapper<teamSettingToggleLogicType> = kea<teamSettingToggleLogicType>([
    props({} as TeamSettingToggleLogicProps),
    key((props) => props.field as string),
    path((key) => ['scenes', 'settings', 'components', 'teamSettingToggleLogic', key]),
    connect(() => ({
        values: [teamLogic, ['currentTeam']],
        actions: [teamLogic, ['updateCurrentTeam', 'updateCurrentTeamSuccess', 'updateCurrentTeamFailure']],
    })),
    actions({
        setValue: (value: boolean) => ({ value }),
        settle: true,
        revert: true,
    }),
    reducers({
        // While a save is in flight we show the value the user just picked, so the
        // toggle reacts instantly instead of waiting for the server round-trip.
        optimisticValue: [
            null as boolean | null,
            {
                setValue: (_, { value }) => value,
                settle: () => null,
                revert: () => null,
            },
        ],
        isSaving: [
            false,
            {
                setValue: () => true,
                settle: () => false,
                revert: () => false,
            },
        ],
    }),
    selectors({
        serverValue: [
            (s) => [s.currentTeam, (_, props) => props.field],
            (currentTeam: TeamPublicType | TeamType | null, field: keyof TeamType): boolean => !!currentTeam?.[field],
        ],
        checked: [
            (s) => [s.optimisticValue, s.serverValue],
            (optimisticValue: boolean | null, serverValue: boolean): boolean =>
                optimisticValue !== null ? optimisticValue : serverValue,
        ],
    }),
    listeners(({ actions, props, values }) => ({
        setValue: ({ value }) => {
            actions.updateCurrentTeam({ [props.field]: value })
        },
        updateCurrentTeamSuccess: ({ payload }) => {
            // Only reconcile once our own field lands; other toggles share this action.
            if (values.isSaving && payload && props.field in payload) {
                actions.settle()
            }
        },
        updateCurrentTeamFailure: () => {
            if (values.isSaving) {
                actions.revert()
                lemonToast.error("Couldn't save that setting. Please try again.")
            }
        },
    })),
])
